import { defineConfig } from "orval";

/**
 * A typed react-query client generated by `bun run sync` from openapi.json,
 * which that script exports from backend-compsoc. Output is committed.
 *
 * No base URL is set: spec paths already start with /api, which is what the
 * browser requests and the Worker forwards unchanged.
 */
export default defineConfig({
	compsoc: {
		input: { target: "./openapi.json" },
		output: {
			target: "src/api/generated/index.ts",
			schemas: "src/api/generated/model",
			client: "react-query",
			httpClient: "fetch",
			mode: "split",
			clean: true,
			override: {
				mutator: { path: "src/api/fetcher.ts", name: "customFetch" },
				fetch: { includeHttpResponseReturnType: false },
			},
		},
	},
});
